#include "virtual_broadcast/broadcaster/si.hpp"
#include <algorithm>
#include <cassert>
#include <chrono>
#include <set>

namespace {
class FakeClock final:public vb::IClock { public:std::chrono::sys_seconds value;std::chrono::sys_seconds Now()const override{return value;} };
std::uint16_t U16(const std::vector<std::uint8_t>&b,std::size_t p){return static_cast<std::uint16_t>((b[p]<<8)|b[p+1]);}
vb::EpgSettings Fixed(int minutes,int days=7){vb::EpgSettings s;s.interval_minutes=minutes;s.schedule_days=days;return s;}
}
int main(){using namespace std::chrono;const auto now=sys_seconds{sys_days{year{2026}/8/30}}+4h+30min; // 13:30 JST
  assert((vb::DurationEncoder::Encode(30min)==std::array<std::uint8_t,3>{0x00,0x30,0x00}));assert((vb::DurationEncoder::Encode(60min)==std::array<std::uint8_t,3>{0x01,0x00,0x00}));assert((vb::DurationEncoder::Encode(90min)==std::array<std::uint8_t,3>{0x01,0x30,0x00}));assert((vb::DurationEncoder::Encode(120min)==std::array<std::uint8_t,3>{0x02,0x00,0x00}));assert((vb::DurationEncoder::Encode(1440min)==std::array<std::uint8_t,3>{0x24,0x00,0x00}));
  for(const int interval:{60,120,1440,75}){const auto schedule=vb::EpgSchedule::Build(Fixed(interval),101,now);const auto repeated=vb::EpgSchedule::Build(Fixed(interval),101,now);assert(!schedule.events().empty()&&schedule.events().front().event_id==repeated.events().front().event_id);for(const auto&e:schedule.events())assert(e.duration==minutes{interval});std::set<std::uint16_t>ids;for(const auto&e:schedule.events())assert(e.event_id&&ids.insert(e.event_id).second);}
  const auto hourly=vb::EpgSchedule::Build(Fixed(60),101,now);auto[present,following]=hourly.PresentFollowing(now);assert(present&&following);assert(present->start_time==sys_seconds{sys_days{year{2026}/8/30}}+4h);assert(following->start_time==sys_seconds{sys_days{year{2026}/8/30}}+5h);assert(hourly.PresentFollowing(sys_seconds{sys_days{year{2026}/8/30}}+3h+59min+59s).first->start_time==sys_seconds{sys_days{year{2026}/8/30}}+3h);assert(hourly.PresentFollowing(sys_seconds{sys_days{year{2026}/8/30}}+4h).first->start_time==sys_seconds{sys_days{year{2026}/8/30}}+4h);
  const auto daily=vb::EpgSchedule::Build(Fixed(1440),101,now);assert(daily.PresentFollowing(now).first->duration==24h);assert(daily.PresentFollowing(sys_seconds{sys_days{year{2026}/8/30}}+14h+59min+59s).first);assert(daily.PresentFollowing(sys_seconds{sys_days{year{2026}/8/30}}+15h).first->start_time==sys_seconds{sys_days{year{2026}/8/30}}+15h);
  vb::AribStringEncoder encoder;for(const auto*text:{"自主放送","松山自主放送ニュース","今日の天気","音楽番組","24時間ライブ","朝のニュースと情報をお送りします"}){const auto encoded=encoder.Encode(text);assert(!encoded.bytes.empty()&&!encoded.replaced);}
  const auto pf=vb::EitPresentFollowingGenerator::Generate(hourly,now,101,32513,32760,encoder);assert(pf.size()==2);for(std::size_t i=0;i<2;++i){const auto&s=pf[i];assert(s[0]==0x4e&&s[6]==i&&s[7]==1);assert(U16(s,3)==101&&U16(s,8)==32513&&U16(s,10)==32760);assert(vb::HasValidMpegCrc(s));assert((((s[1]&15)<<8)|s[2])==s.size()-3);assert(s[26]==vb::kDescriptorShortEvent&&s[28]=='j'&&s[29]=='p'&&s[30]=='n');}
  vb::SiSettings clock_settings;FakeClock fake;fake.value=now;const auto tot=vb::TotGenerator(clock_settings,fake).Generate();assert(tot[5]==0x13&&tot[6]==0x30&&tot[7]==0x00);assert(present->start_time+30min==now);
  const auto expected_start=vb::MjdTimeEncoder::EncodeJst(present->start_time);assert(std::equal(expected_start.begin(),expected_start.end(),pf[0].begin()+16));assert(pf[0][21]==0x01&&pf[0][22]==0x00&&pf[0][23]==0x00);assert(((pf[0][24]>>5)&7)==static_cast<int>(vb::RunningStatus::Running));assert(((pf[1][24]>>5)&7)==static_cast<int>(vb::RunningStatus::NotRunning));assert((pf[0][24]&0x10)==0);
  const auto year_now=sys_seconds{sys_days{year{2026}/12/31}}+15h+30min;const auto year_schedule=vb::EpgSchedule::Build(Fixed(60),101,year_now);const auto year_pf=vb::EitPresentFollowingGenerator::Generate(year_schedule,year_now,101,32513,32760,encoder);assert(U16(year_pf[0],16)==vb::MjdTimeEncoder::Mjd(sys_days{year{2027}/1/1}));assert(year_pf[0][18]==0x00);
  const auto sections=vb::EitScheduleGenerator::Generate(hourly,now,101,32513,32760,encoder);assert(sections.size()>1);assert(sections.front()[0]==0x50);assert(std::any_of(sections.begin(),sections.end(),[](const auto&s){return s[0]==0x51;}));for(const auto&s:sections){assert(s[0]>=0x50&&s[0]<=0x5f&&vb::HasValidMpegCrc(s));assert((((s[1]&15)<<8)|s[2])==s.size()-3);assert(U16(s,3)==101&&U16(s,8)==32513&&U16(s,10)==32760);assert(s[12]>=s[6]&&(s[12]-s[6])<8);assert(s[13]==0x51);}
  vb::EpgSettings explicit_schedule;explicit_schedule.mode=vb::EpgMode::Schedule;for(int i=0;i<20;++i){vb::EpgEvent e;e.event_id=1000+i;e.start_time=sys_seconds{sys_days{year{2026}/8/30}}-9h+minutes{i*5};e.duration=5min;e.title="松山自主放送ニュース";e.short_description=std::string(400,'A');explicit_schedule.events.push_back(e);}const auto many=vb::EpgSchedule::Build(explicit_schedule,101,now);const auto split=vb::EitScheduleGenerator::Generate(many,sys_seconds{sys_days{year{2026}/8/30}}-9h,101,32513,32760,encoder);assert(split.size()>=2&&split[0][6]==0&&split[1][6]==1&&split[0][12]==1);
  vb::EitVersionTracker versions;assert(versions.Update(10)==0&&versions.Update(10)==0&&versions.Update(11)==1);for(int i=0;i<31;++i)versions.Update(12+i);assert(versions.version()==0);
  vb::SiSettings scheduler_settings;vb::SiScheduler scheduler(scheduler_settings);const auto tick=steady_clock::now();assert(scheduler.Due(vb::SiTable::EitPf,tick)&&scheduler.Due(vb::SiTable::EitSchedule,tick));assert(!scheduler.Due(vb::SiTable::EitPf,tick+499ms)&&scheduler.Due(vb::SiTable::EitPf,tick+500ms));assert(!scheduler.Due(vb::SiTable::EitSchedule,tick+1999ms)&&scheduler.Due(vb::SiTable::EitSchedule,tick+2000ms));
  vb::SectionPacketizer packetizer;const auto packets0=packetizer.Packetize(vb::kPidEit,pf[0]);const auto packets1=packetizer.Packetize(vb::kPidEit,pf[1]);assert(!packets0.empty()&&!packets1.empty());for(const auto&p:packets0)assert(vb::PacketPid(p)==vb::kPidEit&&p[0]==0x47);assert((packets1[0][3]&15)==((packets0.back()[3]+1)&15));
  return 0;}
